from typing import Dict, List, Tuple, Union
import ast

Number = Union[int, float]

def dict_to_clamped_list(d: Dict[Union[str, Tuple[int, int]], Number]) -> List[float]:
    """
    Convert a mapping like { "(0, 0)": 98.8, "(0, 1)": 99.53, ... }
    to a flat list of transformed values in row-major order.

    Transform: f(x) = clamp(100 - abs(x), 0, 100)

    - Keys may be strings like "(i, j)" or actual (i, j) tuples.
    - Output is a Python list [f(d[0,0]), f(d[0,1]), f(d[0,2]), ...] sorted by (i, j).
    """
    def transform(x: Number) -> float:
        y = 100.0 - abs(float(x))
        if y < 0.0:
            return 0.0
        if y > 100.0:
            return 100.0
        return y

    def parse_key(k: Union[str, Tuple[int, int]]) -> Tuple[int, int]:
        if isinstance(k, tuple) and len(k) == 2:
            i, j = k
            return int(i), int(j)
        if isinstance(k, str):
            # Safely parse "(i, j)" via ast to tolerate spaces
            tup = ast.literal_eval(k)
            if isinstance(tup, tuple) and len(tup) == 2:
                i, j = tup
                return int(i), int(j)
        raise ValueError(f"Unrecognized key format: {k!r}")

    items = [ (parse_key(k), transform(v)) for k, v in d.items() ]
    items.sort(key=lambda kv: (kv[0][0], kv[0][1]))  # row-major order by (i, j)

    return [val for _, val in items]

